:root {
  --bg: oklch(13% 0.01 260);
  --bg-soft: oklch(17% 0.015 260);
  --surface: oklch(21% 0.02 260);
  --surface-2: oklch(25% 0.025 260);
  --text: oklch(97% 0.01 260);
  --text-muted: oklch(78% 0.02 260);
  --brand: oklch(56% 0.23 28);
  --brand-hover: oklch(61% 0.25 28);
  --border: oklch(31% 0.02 260);
  --success: oklch(75% 0.18 145);
  --radius: 0.75rem;
  --radius-sm: 0.5rem;
  --container: min(1200px, 92vw);
  --shadow: 0 25px 60px oklch(0% 0 0 / 0.45);
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif;
  background: radial-gradient(1200px 800px at 70% -10%, oklch(26% 0.08 25 / 0.32), transparent), var(--bg);
  color: var(--text);
  line-height: 1.5;
}

a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }

.container { width: var(--container); margin: 0 auto; }
.section { padding: clamp(2.75rem, 5vw, 5rem) 0; }

.header {
  position: sticky;
  top: 0;
  z-index: 20;
  background: linear-gradient(to bottom, oklch(10% 0.005 260 / 0.95), oklch(10% 0.005 260 / 0.7));
  backdrop-filter: blur(10px);
  border-bottom: 1px solid oklch(100% 0 0 / 0.08);
}
.nav {
  height: 4.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.brand {
  font-size: clamp(1.4rem, 2.4vw, 2rem);
  font-weight: 900;
  letter-spacing: 0.02em;
  color: var(--brand);
}
.btn {
  border: 0;
  border-radius: var(--radius-sm);
  padding: 0.8rem 1.1rem;
  font-weight: 700;
  cursor: pointer;
}
.btn-primary {
  background: var(--brand);
  color: white;
  transition: transform 0.2s ease, background 0.2s ease;
}
.btn-primary:hover { background: var(--brand-hover); transform: translateY(-1px); }
.btn-ghost {
  background: oklch(100% 0 0 / 0.08);
  color: var(--text);
  border: 1px solid oklch(100% 0 0 / 0.2);
}

.hero {
  min-height: min(88vh, 52rem);
  display: grid;
  align-items: center;
  background:
    linear-gradient(to top, oklch(10% 0.01 260 / 0.95) 8%, oklch(10% 0.01 260 / 0.45) 60%, oklch(10% 0.01 260 / 0.9) 100%),
    url('https://images.unsplash.com/photo-1489599849927-2ee91cede3ba?auto=format&fit=crop&w=1700&q=80') center/cover no-repeat;
  border-bottom: 1px solid oklch(100% 0 0 / 0.08);
}
.hero-content { max-width: 52rem; padding: 5rem 0; }
.hero h1 {
  margin: 0 0 0.8rem;
  font-size: clamp(2rem, 6vw, 4.3rem);
  line-height: 1.02;
  font-weight: 900;
  letter-spacing: -0.02em;
}
.hero p {
  margin: 0.4rem 0;
  font-size: clamp(1rem, 1.7vw, 1.3rem);
  color: var(--text-muted);
}
.price-row {
  margin-top: 1rem;
  display: inline-flex;
  gap: 0.6rem;
  align-items: center;
  background: oklch(0% 0 0 / 0.35);
  border: 1px solid oklch(100% 0 0 / 0.16);
  padding: 0.55rem 0.8rem;
  border-radius: 999px;
}
.price { color: white; font-weight: 800; font-size: 1.1rem; }

.email-form {
  margin-top: 1.4rem;
  display: flex;
  gap: 0.65rem;
  flex-wrap: wrap;
}
.input {
  flex: 1 1 16rem;
  min-height: 3rem;
  border-radius: var(--radius-sm);
  border: 1px solid oklch(100% 0 0 / 0.24);
  background: oklch(0% 0 0 / 0.45);
  color: var(--text);
  padding: 0 0.9rem;
  outline: none;
}
.input:focus { border-color: var(--brand); box-shadow: 0 0 0 3px oklch(56% 0.23 28 / 0.22); }

.section-title {
  font-size: clamp(1.5rem, 3.2vw, 2.4rem);
  margin: 0 0 1rem;
  font-weight: 800;
}
.section-subtitle {
  margin: 0 0 1.7rem;
  color: var(--text-muted);
}

.carousel-wrap {
  position: relative;
}
.carousel {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: clamp(10.5rem, 18vw, 12rem);
  gap: 1rem;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: thin;
  padding-bottom: 0.3rem;
}
.carousel::-webkit-scrollbar { height: 8px; }
.carousel::-webkit-scrollbar-thumb { background: oklch(100% 0 0 / 0.2); border-radius: 99px; }
.poster {
  position: relative;
  min-height: 16rem;
  border-radius: var(--radius);
  overflow: hidden;
  scroll-snap-align: start;
  border: 1px solid oklch(100% 0 0 / 0.16);
  background: linear-gradient(155deg, oklch(35% 0.08 28), oklch(24% 0.03 260));
}
.poster:nth-child(2n) { background: linear-gradient(155deg, oklch(29% 0.11 20), oklch(19% 0.05 280)); }
.poster:nth-child(3n) { background: linear-gradient(155deg, oklch(26% 0.09 185), oklch(19% 0.03 255)); }
.rank {
  position: absolute;
  inset: auto auto 0.35rem 0.35rem;
  font-size: 4.5rem;
  font-weight: 900;
  color: oklch(100% 0 0 / 0.24);
  line-height: 1;
}
.poster-title {
  position: absolute;
  inset: auto 0.65rem 0.6rem 0.65rem;
  font-size: 1rem;
  font-weight: 700;
  text-shadow: 0 2px 12px oklch(0% 0 0 / 0.8);
}
.arrow-btn {
  position: absolute;
  top: 45%;
  transform: translateY(-50%);
  width: 2.4rem;
  height: 2.4rem;
  border-radius: 50%;
  border: 1px solid oklch(100% 0 0 / 0.25);
  background: oklch(0% 0 0 / 0.6);
  color: white;
  cursor: pointer;
}
.arrow-left { left: -0.6rem; }
.arrow-right { right: -0.6rem; }

.features-grid {
  display: grid;
  gap: 1rem;
  grid-template-columns: repeat(4, minmax(0, 1fr));
}
.card {
  background: linear-gradient(160deg, var(--surface), var(--surface-2));
  border: 1px solid var(--border);
  padding: 1.1rem;
  border-radius: var(--radius);
}
.card h3 { margin: 0 0 0.5rem; font-size: 1.05rem; }
.card p { margin: 0; color: var(--text-muted); font-size: 0.96rem; }

.faq-list { display: grid; gap: 0.75rem; }
.faq-item {
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  overflow: hidden;
  background: var(--surface);
}
.faq-q {
  width: 100%;
  text-align: left;
  padding: 1rem;
  background: none;
  color: var(--text);
  border: 0;
  display: flex;
  justify-content: space-between;
  font-size: 1rem;
  font-weight: 700;
  cursor: pointer;
}
.faq-a {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.28s ease;
}
.faq-a p { margin: 0; padding: 0 1rem 1rem; color: var(--text-muted); }
.faq-item.active .faq-a { max-height: 180px; }

.cta-panel {
  background: linear-gradient(155deg, oklch(24% 0.05 260), oklch(22% 0.09 25));
  border: 1px solid oklch(100% 0 0 / 0.12);
  border-radius: var(--radius);
  padding: clamp(1rem, 3.5vw, 2.2rem);
}

.footer {
  border-top: 1px solid oklch(100% 0 0 / 0.1);
  padding: 2rem 0 3rem;
  color: var(--text-muted);
}
.footer-grid {
  margin-top: 1rem;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.75rem;
}
.footer-grid a { text-decoration: underline; text-underline-offset: 2px; }

.auth-page {
  min-height: 100vh;
  display: grid;
  grid-template-rows: auto 1fr auto;
  background:
    linear-gradient(to top, oklch(12% 0.01 260 / 0.94), oklch(12% 0.01 260 / 0.6)),
    url('https://images.unsplash.com/photo-1478720568477-152d9b164e26?auto=format&fit=crop&w=1500&q=80') center/cover no-repeat;
}
.login-wrap {
  display: grid;
  place-items: center;
  padding: 2rem 0;
}
.login-card {
  width: min(28rem, 92vw);
  background: oklch(10% 0.01 260 / 0.8);
  border: 1px solid oklch(100% 0 0 / 0.16);
  border-radius: var(--radius);
  padding: 1.25rem;
  box-shadow: var(--shadow);
}
.login-card h1 { margin: 0 0 1rem; font-size: 1.8rem; }
.login-form { display: grid; gap: 0.8rem; }
.login-form .btn-primary { min-height: 2.9rem; }

.help-toggle {
  margin-top: 1rem;
  background: none;
  border: 0;
  color: var(--text-muted);
  text-decoration: underline;
  text-underline-offset: 2px;
  cursor: pointer;
  padding: 0;
}
.help-panel {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.28s ease;
}
.help-panel.open { max-height: 220px; }
.help-panel p, .help-panel li { color: var(--text-muted); }

@media (max-width: 980px) {
  .features-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .arrow-btn { display: none; }
}
@media (max-width: 640px) {
  .nav { height: 4rem; }
  .hero-content { padding: 3.5rem 0; }
  .email-form { flex-direction: column; }
  .email-form .btn { width: 100%; }
  .footer-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
